import{_ as e,c as i,o as s,ag as r}from"./chunks/framework.B-XtCDNB.js";const m=JSON.parse('{"title":"Bindings","description":"Bindings Mono: runtime bindings (wrappers), GAPI tools, .sources files with XML syntax Vala: no runtime bindings necessary, Vala method calls are direct C function calls, mapped by *.vapi (Vala API)...","frontmatter":{"prev":{"text":"GTK+ Demo App","link":"/guides/vala-for-csharp-programmers/37-gtk-demo-app"},"next":{"text":"Vala for Java Programmers","link":"/guides/vala-for-java-programmers"}},"headers":[],"relativePath":"guides/vala-for-csharp-programmers/38-bindings.md","filePath":"guides/vala-for-csharp-programmers/38-bindings.md","lastUpdated":1785610900000}'),n={name:"guides/vala-for-csharp-programmers/38-bindings.md"};function t(l,a,o,p,d,c){return s(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="bindings" tabindex="-1">Bindings <a class="header-anchor" href="#bindings" aria-label="Permalink to &quot;Bindings&quot;">​</a></h1><p>Mono: runtime bindings (<em>wrappers</em>), GAPI tools, <em>.sources</em> files with XML syntax</p><p>Vala: no runtime bindings necessary, Vala method calls are direct C function calls, mapped by <em>*.vapi</em> (Vala API) files with Vala syntax, annotated with attributes like <code>[CCode (...)]</code></p><p>On Unix systems VAPI files are usually installed in</p><ul><li><em>/usr/share/vala/vapi/</em> or</li><li><em>/usr/local/share/vala/vapi/</em></li></ul><p>Using a vapi file (e.g. foo-1.0.vapi):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">valac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source.vala</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foo-1.0</span></span></code></pre></div><p>The Vala compiler will additionally look for a corresponding <a href="https://www.freedesktop.org/wiki/Software/pkg-config/" target="_blank" rel="noreferrer">pkg-config</a> file (<em>*.pc</em>) with the same base name (e.g. <em>foo-1.0.pc</em>), usually located in</p><ul><li><em>/usr/lib/pkgconfig/</em> or</li><li><em>/usr/local/lib/pkgconfig/</em></li></ul><p>and pass its configuration to the C compiler if existing.</p><p>VAPI files are either <a href="https://wiki.gnome.org/Projects/Vala/Bindings" target="_blank" rel="noreferrer">auto-generated</a> for GObject libraries or hand-written for non-GObject libraries.</p>',11)])])}const h=e(n,[["render",t]]);export{m as __pageData,h as default};
